	require.Equal(t, seedA.Header.Revision, final.Kvs[0].CreateRevision)
	require.Equal(t, seedA.Header.Revision, final.Kvs[0].ModRevision)
	require.Equal(t, int64(1), final.Kvs[0].Version)
